sealed interface Conn permits Disconnected, Connected, Auth {}

record Disconnected(String host) implements Conn {
    Connected connect() { return new Connected(host); }         // only on Disconnected
}
record Connected(String host) implements Conn {
    Auth login(String token) { return new Auth(host, token); }  // only on Connected
    Disconnected disconnect() { return new Disconnected(host); }
}
record Auth(String host, String token) implements Conn {
    String profile() { return "profile-of-" + token; }          // only when authenticated
}
